WITH bounds AS (
 SELECT COALESCE([[{{start_date}}::date,]] date_trunc('month', now() AT TIME ZONE 'Asia/Irkutsk')::date) AS start_day,
 COALESCE([[{{end_date}}::date,]] (date_trunc('month', now() AT TIME ZONE 'Asia/Irkutsk') + interval '1 month - 1 day')::date) AS end_day
), p AS (
 SELECT start_day::timestamp AT TIME ZONE 'Asia/Irkutsk' AS lo,
 CASE WHEN r.snapshot_at IS NOT NULL THEN LEAST((end_day + 1)::timestamp AT TIME ZONE 'Asia/Irkutsk', r.snapshot_at) END AS hi FROM bounds CROSS JOIN analytics.refresh_state r WHERE r.id=1
), last_closed AS (
 SELECT DISTINCT ON (ticket_id) * FROM analytics.events, p
 WHERE kind='closed' AND occurred_at >= p.lo AND occurred_at < p.hi
 ORDER BY ticket_id, occurred_at DESC, id DESC
), selected AS (SELECT CASE WHEN NOT t.incomplete AND q.occurred_at>=t.created_at THEN EXTRACT(EPOCH FROM (q.occurred_at-t.created_at)) END AS seconds FROM last_closed q JOIN analytics.tickets t ON t.id=q.ticket_id WHERE true [[ AND q.department = {{department}} ]]
[[ AND q.actor_id = {{employee}} ]]
[[ AND t.company_id = {{company}} ]]), totals AS (SELECT avg(seconds) AS average,percentile_cont(0.5) WITHIN GROUP(ORDER BY seconds) AS median,max(seconds) AS maximum,count(seconds) AS known FROM selected) SELECT coalesce(CASE WHEN average IS NULL THEN NULL WHEN average<60 THEN '< 1 мин' WHEN floor((average) / 60)::bigint<60 THEN floor((average) / 60)::bigint||' мин' ELSE (floor((average) / 60)::bigint / 60)||' '||CASE WHEN (floor((average) / 60)::bigint / 60)%10=1 AND (floor((average) / 60)::bigint / 60)%100<>11 THEN 'час' WHEN (floor((average) / 60)::bigint / 60)%10 BETWEEN 2 AND 4 AND (floor((average) / 60)::bigint / 60)%100 NOT BETWEEN 12 AND 14 THEN 'часа' ELSE 'часов' END ||CASE WHEN (floor((average) / 60)::bigint % 60)=0 THEN '' ELSE ' '||(floor((average) / 60)::bigint % 60)||' мин' END END,'—') AS "Среднее время",coalesce(CASE WHEN median IS NULL THEN NULL WHEN median<60 THEN '< 1 мин' WHEN floor((median) / 60)::bigint<60 THEN floor((median) / 60)::bigint||' мин' ELSE (floor((median) / 60)::bigint / 60)||' '||CASE WHEN (floor((median) / 60)::bigint / 60)%10=1 AND (floor((median) / 60)::bigint / 60)%100<>11 THEN 'час' WHEN (floor((median) / 60)::bigint / 60)%10 BETWEEN 2 AND 4 AND (floor((median) / 60)::bigint / 60)%100 NOT BETWEEN 12 AND 14 THEN 'часа' ELSE 'часов' END ||CASE WHEN (floor((median) / 60)::bigint % 60)=0 THEN '' ELSE ' '||(floor((median) / 60)::bigint % 60)||' мин' END END,'—') AS "Медианное время",coalesce(CASE WHEN maximum IS NULL THEN NULL WHEN maximum<60 THEN '< 1 мин' WHEN floor((maximum) / 60)::bigint<60 THEN floor((maximum) / 60)::bigint||' мин' ELSE (floor((maximum) / 60)::bigint / 60)||' '||CASE WHEN (floor((maximum) / 60)::bigint / 60)%10=1 AND (floor((maximum) / 60)::bigint / 60)%100<>11 THEN 'час' WHEN (floor((maximum) / 60)::bigint / 60)%10 BETWEEN 2 AND 4 AND (floor((maximum) / 60)::bigint / 60)%100 NOT BETWEEN 12 AND 14 THEN 'часа' ELSE 'часов' END ||CASE WHEN (floor((maximum) / 60)::bigint % 60)=0 THEN '' ELSE ' '||(floor((maximum) / 60)::bigint % 60)||' мин' END END,'—') AS "Максимальное время",known AS "Измеренных сроков" FROM totals
